package("nexus-boringssl-crypto")
    set_homepage("https://boringssl.googlesource.com/boringssl/")
    set_description("Pinned static BoringSSL libcrypto only")
    set_license("Apache-2.0")
    add_urls(os.getenv("NEXUS_BORINGSSL_SOURCE") or "https://boringssl.googlesource.com/boringssl.git")
    add_versions("0.1.0", "e651545da6e26e1f4420723a3b69a78ed1b9c51d")
    add_links("crypto")
    add_syslinks("pthread")
    on_install("linux", function (package)
        import("package.tools.cmake")
        local builddir = "build-nexus"
        local configs = {"-DBUILD_SHARED_LIBS=OFF", "-DBUILD_TESTING=OFF", "-DCMAKE_CXX_SCAN_FOR_MODULES=OFF",
                         "-DCMAKE_CXX_FLAGS=-fno-exceptions -fno-rtti"}
        cmake.build(package, configs, {target = "crypto", builddir = builddir})
        local archive = path.join(builddir, "libcrypto.a")
        assert(os.isfile(archive), "BoringSSL crypto archive missing")
        os.cp(archive, package:installdir("lib"))
        os.cp("include/*", package:installdir("include"))
        os.cp("LICENSE", package:installdir("share/licenses/nexus-boringssl-crypto"))
    end)
    on_test(function (package)
        assert(package:has_cincludes("openssl/aead.h"))
    end)
package_end()
